package com.filmax.core.tv.designsystem

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathNode
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

/**
 * Логотипы источников рейтинга — одноцветные вектора (буква/лепестки вырезаны заливкой evenOdd,
 * как в оригинальных монохромных иконках IMDb/Кинопоиска), поэтому красятся через `tint` в
 * `Icon()`, как и Material-иконки: свой `fillColor` в path не имеет значения.
 */
private fun pathNodesOf(pathData: String): List<PathNode> = PathParser().parsePathString(pathData).toNodes()

val ImdbLogo: ImageVector by lazy {
    ImageVector.Builder(
        name = "ImdbLogo",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 56f,
        viewportHeight = 56f,
    ).addPath(
        pathData = pathNodesOf(IMDB_PATH),
        pathFillType = PathFillType.EvenOdd,
        fill = SolidColor(Color.Black),
    ).build()
}

val KinopoiskLogo: ImageVector by lazy {
    ImageVector.Builder(
        name = "KinopoiskLogo",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 56f,
        viewportHeight = 56f,
    ).addPath(
        pathData = pathNodesOf(KINOPOISK_PATH),
        pathFillType = PathFillType.EvenOdd,
        fill = SolidColor(Color.Black),
    ).build()
}

